DECLARE @EmpresasDestino TABLE (CompanyId NVARCHAR(40));

IF OBJECT_ID(N'Empresas', N'U') IS NOT NULL
BEGIN
    INSERT INTO @EmpresasDestino (CompanyId)
    SELECT DISTINCT Id FROM Empresas;
END;

IF NOT EXISTS (SELECT 1 FROM @EmpresasDestino)
BEGIN
    INSERT INTO @EmpresasDestino (CompanyId) VALUES (N'empresa-principal');
END;

MERGE INTO Produtos AS target
USING (
    SELECT e.CompanyId, t.ProductCode, t.ProductName, t.Gtin, t.Unidade, t.ProductUnitPrice, t.ProductSalePrice
    FROM #ProdutosMercadoTemp t
    CROSS JOIN @EmpresasDestino e
) AS source
ON target.CompanyId = source.CompanyId AND target.ProductCode = source.ProductCode
WHEN MATCHED THEN
    UPDATE SET 
        target.ProductName = source.ProductName,
        target.Gtin = CASE WHEN source.Gtin <> N'SEM GTIN' THEN source.Gtin ELSE target.Gtin END,
        target.UnidadeComercial = source.Unidade,
        target.UnidadeTributavel = source.Unidade,
        target.ProductUnitPrice = CASE WHEN source.ProductUnitPrice > 0 THEN source.ProductUnitPrice ELSE target.ProductUnitPrice END,
        target.ProductSalePrice = source.ProductSalePrice
WHEN NOT MATCHED THEN
    INSERT
    (
        Id,
        CompanyId,
        ProductImageUrl,
        ProductImageName,
        ProductName,
        ProductCode,
        ProductSupplier,
        SupplierId,
        ProductDescription,
        ProductQnt,
        ProductUnitPrice,
        ProductSalePrice,
        TotalPriceOnProduct,
        MargemDesejadaPercentual,
        Ncm,
        Cest,
        Cfop,
        OrigemMercadoria,
        UnidadeComercial,
        UnidadeTributavel,
        Gtin,
        CsosnIcms,
        CstIcms,
        AliquotaIcms,
        CstPis,
        CstCofins,
        CstIbsCbs,
        CClassTrib
    )
    VALUES
    (
        LOWER(NEWID()),
        source.CompanyId,
        N'',
        N'',
        source.ProductName,
        source.ProductCode,
        N'Importação Legado CDS',
        NULL,
        N'Importado da base legado exp_cadprodutos.cds',
        100.0000,
        source.ProductUnitPrice,
        source.ProductSalePrice,
        0.00,
        NULL,
        N'00000000',
        NULL,
        N'5102',
        0,
        source.Unidade,
        source.Unidade,
        source.Gtin,
        N'102',
        NULL,
        0.0000,
        N'07',
        N'07',
        NULL,
        NULL
    );

DROP TABLE #ProdutosMercadoTemp;
GO
